import{_ as t,o,c as r,a2 as s}from"./chunks/framework.BXzK3EA4.js";const a="/assets/image-key2025030604.CRZe4xdw.png",n="/assets/image-key2025030605.M1WpYft-.png",i="/assets/image-key2025030609en.D6A6txWK.png",l="/assets/image-key2025030610.zBAXA-oL.png",h="/assets/image-key2025030611.5KXV_KbB.png",d="/assets/image-key2025030612.BVcf3FKa.png",p="/assets/image-key2025030613.CRj7VfPW.png",c="/assets/image-key2025030614en.DrnSM4Tq.png",m="/assets/image-key2025030615en.BBM8yndg.png",b=JSON.parse('{"title":"How to use a private key for remote login","description":"","frontmatter":{"title":"How to use a private key for remote login"},"headers":[],"relativePath":"operations-knowledge-base/vps/how-to-use-a-private-key-for-remote-login.md","filePath":"operations-knowledge-base/vps/how-to-use-a-private-key-for-remote-login.md","lastUpdated":1794311093000}'),g={name:"operations-knowledge-base/vps/how-to-use-a-private-key-for-remote-login.md"};function u(y,e,f,k,v,w){return o(),r("div",null,[...e[0]||(e[0]=[s('<h2 id="this-article-introduces-how-to-use-a-private-key-for-remote-login-with-different-systems-and-remote-tools" tabindex="-1"><strong>This article introduces how to use a private key for remote login with different systems and remote tools</strong> <a class="header-anchor" href="#this-article-introduces-how-to-use-a-private-key-for-remote-login-with-different-systems-and-remote-tools" aria-label="Permalink to &quot;**This article introduces how to use a private key for remote login with different systems and remote tools**&quot;">​</a></h2><h2 id="configure-the-ssh-service-to-allow-key-based-login" tabindex="-1">Configure the SSH service to allow key-based login <a class="header-anchor" href="#configure-the-ssh-service-to-allow-key-based-login" aria-label="Permalink to &quot;Configure the SSH service to allow key-based login&quot;">​</a></h2><p>On the <strong>remote server</strong>, ensure that the configuration of SSH allows key authentication:</p><ol><li>Edit the file <code>/etc/ssh/sshd_config</code> :</li></ol><p>#sudo vi /etc/ssh/sshd_config</p><pre><code>2. Make sure the following lines exist and uncommented(no `#`):\n</code></pre><p>PubkeyAuthentication yes</p><p>AuthorizedKeysFile .ssh/authorized_keys</p><p>PasswordAuthentication no # when you wish to disable password authentication</p><h2 id="i-login-method-via-mac-terminal" tabindex="-1">I. Login Method via Mac Terminal <a class="header-anchor" href="#i-login-method-via-mac-terminal" aria-label="Permalink to &quot;I. Login Method via Mac Terminal&quot;">​</a></h2><h2 id="_1-download-the-private-key-from-the-remote-server" tabindex="-1">1. Download the private key from the remote server <a class="header-anchor" href="#_1-download-the-private-key-from-the-remote-server" aria-label="Permalink to &quot;1. Download the private key from the remote server&quot;">​</a></h2><p>1.1 Use the SCP command to download the private key</p><p>Assuming the remote server&#39;s IP address is 192.168.1.100, the username is root, and the private key file is located at /root/.ssh/id_ed25519 on the remote server, you can use the SCP (Secure Copy Protocol) to download the private key to your Mac.</p><p>Execute the following command on <strong>the Mac terminal</strong>:</p><p>#scp <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a>:/root/.ssh/id_ed25519 ~/.ssh/id_ed25519</p><ul><li><strong><code>root@192.168.1.100</code>：The remote server&#39;s username and IP address.</strong></li><li><strong>/root/.ssh/id_ed25519:The path to the private key on the remote server.</strong></li><li><strong><code>~/.ssh/id_ed25519</code>:The path where the private key is stored on the local Mac computer.</strong></li></ul><p><strong>If you want to specify the remote server&#39;s port, use <code>-P</code> (uppercase P) followed by the port number.</strong></p><p>#scp -P 56251 <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a>:/root/.ssh/id_ed25519 ~/.ssh/id_ed25519</p><p><strong>1.2 Enter the password.</strong></p><p>When executing the above command, the system will prompt you to enter the remote server&#39;s password. After entering the password, the private key will be securely copied to the local <code>~/.ssh/</code> directory.</p><p><strong>For example:</strong></p><p><strong><img src="'+a+'" alt=""></strong></p><h2 id="_2-ensure-the-correct-permissions-for-the-private-key" tabindex="-1">2.Ensure the correct permissions for the private key. <a class="header-anchor" href="#_2-ensure-the-correct-permissions-for-the-private-key" aria-label="Permalink to &quot;2.Ensure the correct permissions for the private key.&quot;">​</a></h2><p>2.1 SSH requires the private key file to have specific permissions. Ensure the private key&#39;s permissions are set to 600, meaning only the file&#39;s owner can read and write it.</p><p>Execute the following command on <strong>the Mac terminal</strong>:</p><p>#chmod 600 ~/.ssh/id_ed25519</p><h2 id="_3-use-the-private-key-to-log-in-to-the-remote-server" tabindex="-1">3. Use the private key to log in to the remote server <a class="header-anchor" href="#_3-use-the-private-key-to-log-in-to-the-remote-server" aria-label="Permalink to &quot;3. Use the private key to log in to the remote server&quot;">​</a></h2><p>3.1 Use the <code>ssh</code> command to connect it</p><p>Now that you have downloaded <strong>the private key</strong> to your <strong>Mac</strong> and set the correct permissions, you can use <strong>SSH</strong> to connect to the remote server.</p><p>Run the following command:</p><p>#ssh -i ~/.ssh/id_ed25519 <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a></p><ul><li><strong><code>-i ~/.ssh/id_ed25519</code>: Specify the private key file.</strong></li><li><strong><code>root@192.168.1.100</code>: The remote server&#39;s username and IP address.</strong></li><li><strong>If you need to specify the SSH port of the remote server, add <code>-p 56251</code> at the end.</strong></li></ul><p><strong>For example:</strong></p><p><img src="'+n+'" alt=""></p><p>If the private key does not have a passphrase, SSH will log in directly. If a passphrase is set, the system will prompt you to enter it.</p><h2 id="ii-windows-system" tabindex="-1">II. windows system <a class="header-anchor" href="#ii-windows-system" aria-label="Permalink to &quot;II. windows system&quot;">​</a></h2><h2 id="_1-download-the-private-key-to-a-windows-system" tabindex="-1">1. Download the private key to a Windows system. <a class="header-anchor" href="#_1-download-the-private-key-to-a-windows-system" aria-label="Permalink to &quot;1. Download the private key to a Windows system.&quot;">​</a></h2><p>Download private key using SCP or FileZilla.</p><ul><li>If you have SSH access, you can use SCP or FileZilla to download the private key from the remote server to Windows.</li><li>For example, to download the key to your local machine using FileZilla:</li></ul><p><img src="'+i+'" alt=""></p><h2 id="iii-putty-connection-method" tabindex="-1">III. Putty connection method. <a class="header-anchor" href="#iii-putty-connection-method" aria-label="Permalink to &quot;III. Putty connection method.&quot;">​</a></h2><h2 id="_1-download-and-install-putty-and-puttygen" tabindex="-1">1.Download and install PuTTY and PuTTYgen： <a class="header-anchor" href="#_1-download-and-install-putty-and-puttygen" aria-label="Permalink to &quot;1.Download and install PuTTY and PuTTYgen：&quot;">​</a></h2><p>1.1 Open PuTTYgen, load the downloaded id_rsa private key file, and save it.</p><p>1.2 Finally, click <em>Save private key</em> to generate the private key file.</p><p><img src="'+l+'" alt=""></p><h2 id="_2-configure-the-session" tabindex="-1">2.Configure the session: <a class="header-anchor" href="#_2-configure-the-session" aria-label="Permalink to &quot;2.Configure the session:&quot;">​</a></h2><h2 id="open-putty" tabindex="-1">Open PuTTY <a class="header-anchor" href="#open-putty" aria-label="Permalink to &quot;Open PuTTY&quot;">​</a></h2><p>2.1 Enter the server&#39;s IP address in the Host Name (or IP address) field.</p><p>2.2 Enter the SSH port (e.g., 56251) in the Port field.</p><p>2.3 Select <strong>SSH</strong> in the <strong>Connection type</strong>.</p><p><img src="'+h+'" alt=""></p><h2 id="_3-load-the-private-key" tabindex="-1">3. Load the private key: <a class="header-anchor" href="#_3-load-the-private-key" aria-label="Permalink to &quot;3. Load the private key:&quot;">​</a></h2><p>3.1 In the left-hand menu, expand <strong>Connection &gt; SSH &gt; Auth</strong>.</p><p>3.2 Under <strong>Private key file for authentication</strong>, click <strong>Browse</strong> and select the <code>.ppk</code> file you saved (for example, <code>id_ed25519.ppk</code>).</p><p><img src="'+d+'" alt=""></p><h2 id="_4-connect-to-server" tabindex="-1">4. Connect to server： <a class="header-anchor" href="#_4-connect-to-server" aria-label="Permalink to &quot;4. Connect to server：&quot;">​</a></h2><p>4.1 Click <em><strong>Open</strong></em> to start the connection.</p><p>4.2 Enter the username (e.g., root) and press Enter.</p><p>4.3 If everything goes well, you should be successfully logged into the server.</p><p><img src="'+p+'" alt=""></p><h2 id="_4-xshell-connection-method" tabindex="-1">4. xshell connection method <a class="header-anchor" href="#_4-xshell-connection-method" aria-label="Permalink to &quot;4. xshell connection method&quot;">​</a></h2><h2 id="open-xshell" tabindex="-1">Open Xshell: <a class="header-anchor" href="#open-xshell" aria-label="Permalink to &quot;Open Xshell:&quot;">​</a></h2><ol><li>Create a new session:</li></ol><p>Click <em><strong>File</strong></em> &gt; <em><strong>New</strong></em> on the menu bar to open the New Session window.</p><ol start="2"><li>Configure connection information:</li></ol><p>In the Connection tab:</p><ul><li><strong>Name</strong>: Enter the session&#39;s name.</li><li><strong>Protocol</strong>: Select <strong>SSH</strong>.</li><li><strong>Host</strong>: Enter the server&#39;s IP address (for example, 107.149.212.85).</li><li><strong>Port Number</strong>: Enter the SSH port (for example, 56251).</li></ul><p><img src="'+c+'" alt=""></p><ol start="3"><li><strong>Configure Authentication</strong></li></ol><ul><li><strong>User key</strong>: Click <em><strong>Browse</strong></em> and select the private key file you downloaded to your local computer (such as id_ed25519).</li><li>If the private key has a password, enter its password in <strong>Password</strong>.</li></ul><p><img src="'+m+'" alt=""></p>',71)])])}const P=t(g,[["render",u]]);export{b as __pageData,P as default};
